# Lunar Konstruksi - Fase 7 Full Public Redesign
# Smart installer: professional public redesign on top of Phase 1-6 foundations.
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Phase([string]$Message) { Write-Host "[FASE 7] $Message" -ForegroundColor Cyan }
function Fail-Phase([string]$Message) { Write-Host ""; Write-Host "[FASE 7] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Phase "Jalankan script ini dari repository Git Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$branch = (& git branch --show-current).Trim()
$head = (& git rev-parse --short HEAD).Trim()
Write-Phase "Repo   : $repoRoot"
Write-Phase "Branch : $branch"
Write-Phase "HEAD   : $head"

$trackedStatus = & git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { Fail-Phase "Tidak bisa membaca git status." }
if ($trackedStatus) { Write-Host $trackedStatus; Fail-Phase "Ada perubahan TRACKED yang belum disimpan. Commit/stash dulu agar installer aman." }

$required = @(
  "package.json",
  "components/site/home-page.tsx",
  "components/site/about-page.tsx",
  "components/site/services-page.tsx",
  "components/site/projects-page.tsx",
  "components/site/contact-page.tsx",
  "components/site/site-header.tsx",
  "components/site/site-footer.tsx",
  "features/public-site/server.ts",
  "features/public-site/public-site.types.ts",
  "features/navigation/server.ts",
  "features/site-settings/server.ts",
  "components/admin/cms/cms-dashboard.tsx",
  "app/api/public/leads/route.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { Write-Host "[FASE 7] Prasyarat yang belum ada:" -ForegroundColor Yellow; $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Phase "Pastikan Fase 1-6 sudah terpasang pada branch lokal ini." }

if (Test-Path -LiteralPath "components/site/redesign/public-page-renderer.tsx") { Write-Host "[FASE 7] Info: folder redesign publik sudah ada. File akan diperbarui sesuai desain Fase 7." -ForegroundColor Yellow }

Write-Phase "Prasyarat aman. Menyiapkan Full Public Redesign..."
$payload = @{}
$payload["PHASE7_PUBLIC_REDESIGN.md"] = ""
$payload["components/site/about-page.tsx"] = ""
$payload["components/site/contact-page.tsx"] = ""
$payload["components/site/home-page.tsx"] = ""
$payload["components/site/projects-page.tsx"] = ""
$payload["components/site/redesign/public-contact-form.tsx"] = ""
$payload["components/site/redesign/public-footer.tsx"] = ""
$payload["components/site/redesign/public-header.tsx"] = ""
$payload["components/site/redesign/public-helpers.ts"] = ""
$payload["components/site/redesign/public-page-renderer.tsx"] = ""
$payload["components/site/services-page.tsx"] = ""
$payload["components/site/site-footer.tsx"] = ""
$payload["components/site/site-header.tsx"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[FASE 7] write  $($entry.Key)" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "[FASE 7] Full Public Redesign selesai diterapkan." -ForegroundColor Green
Write-Host "[FASE 7] Home/About/Services/Projects/Contact kini memakai visual system premium baru." -ForegroundColor Green
Write-Host "[FASE 7] Tidak ada dependency baru; npm install tidak diperlukan." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi berikutnya:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git diff --check"
Write-Host "  git status --short"
